final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: Creates an IoT Core device onboarding policy via a Lambda-backed custom resource

Parameters:
  PolicyNamePrefix:
    Type: String
    Default: DeviceOnboardingPolicy
    Description: Prefix for the generated IoT policy name
    AllowedPattern: '^[a-zA-Z0-9:_-]+$'

Resources:
  LambdaExecutionRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: lambda.amazonaws.com
            Action: sts:AssumeRole
      ManagedPolicyArns:
        - arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole
      Policies:
        - PolicyName: IotPolicyManagement
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - iot:CreatePolicy
                  - iot:DeletePolicy
                  - iot:GetPolicy
                  - iot:CreatePolicyVersion
                  - iot:DeletePolicyVersion
                  - iot:ListPolicyVersions
                  - iot:AttachPrincipalPolicy
                  - iot:DetachPrincipalPolicy
                Resource: '*'

  OnboardingPolicyFunction:
    Type: AWS::Lambda::Function
    Properties:
      Runtime: nodejs24.x
      Handler: index.handler
      Timeout: 60
      MemorySize: 128
      Role: !GetAtt LambdaExecutionRole.Arn
      Code:
        ZipFile: |
          const { CloudFormationCustomResourceEvent, Context } = require('aws-lambda');
          const { IoTClient, CreatePolicyCommand, DeletePolicyCommand, CreatePolicyVersionCommand, DeletePolicyVersionCommand } = require('@aws-sdk/client-iot');
          const response = require('cfn-response');
          const iot = new IoTClient({});

          const policyDocument = {
            Version: '2012-10-17',
            Statement: [
              {
                Effect: 'Allow',
                Action: ['iot:Connect'],
                Resource: [
                  'arn:aws:iot:*:*:client/${iot:Connection.Thing.ThingName}'
                ]
              },
              {
                Effect: 'Allow',
                Action: ['iot:Publish', 'iot:Receive'],
                Resource: [
                  'arn:aws:iot:*:*:topic/${iot:Connection.Thing.ThingName}/*'
                ]
              },
              {
                Effect: 'Allow',
                Action: ['iot:Subscribe'],
                Resource: [
                  'arn:aws:iot:*:*:topicfilter/${iot:Connection.Thing.ThingName}/*'
                ]
              }
            ]
          };

          exports.handler = async (event, context) => {
            const policyName = `${process.env.POLICY_NAME_PREFIX}-${event.PhysicalResourceId || context.logStreamName || 'default'}`;
            try {
              if (event.RequestType === 'Create') {
                const name = `${process.env.POLICY_NAME_PREFIX}-${context.logStreamName}`;
                await iot.send(new CreatePolicyCommand({
                  policyName: name,
                  policyDocument: JSON.stringify(policyDocument)
                }));
                await response.send(event, context, response.SUCCESS, { PolicyName: name }, name);
              } else if (event.RequestType === 'Update') {
                const name = event.PhysicalResourceId;
                const versions = await iot.send(new ListPolicyVersionsCommand({ policyName: name }));
                const nonDefault = versions.versions.filter(v => !v.isDefaultVersion);
                for (const v of nonDefault) {
                  await iot.send(new DeletePolicyVersionCommand({ policyName: name, policyVersionId: v.versionId }));
                }
                await iot.send(new CreatePolicyVersionCommand({
                  policyName: name,
                  policyDocument: JSON.stringify(policyDocument),
                  setAsDefault: true
                }));
                await response.send(event, context, response.SUCCESS, { PolicyName: name }, name);
              } else if (event.RequestType === 'Delete') {
                const name = event.PhysicalResourceId;
                try {
                  const versions = await iot.send(new ListPolicyVersionsCommand({ policyName: name }));
                  for (const v of versions.versions) {
                    if (!v.isDefaultVersion) {
                      await iot.send(new DeletePolicyVersionCommand({ policyName: name, policyVersionId: v.versionId }));
                    }
                  }
                  await iot.send(new DeletePolicyCommand({ policyName: name }));
                } catch (err) {
                  if (err.name !== 'ResourceNotFoundException') {
                    throw err;
                  }
                }
                await response.send(event, context, response.SUCCESS, { PolicyName: name }, name);
              }
            } catch (err) {
              console.error('Error:', err);
              await response.send(event, context, response.FAILED, { Message: err.message }, policyName);
            }
          };
      Environment:
        Variables:
          POLICY_NAME_PREFIX: !Ref PolicyNamePrefix

  DeviceOnboardingPolicy:
    Type: Custom::IotDeviceOnboardingPolicy
    DependsOn: OnboardingPolicyFunction
    Properties:
      ServiceToken: !GetAtt OnboardingPolicyFunction.Arn

Outputs:
  PolicyName:
    Description: Name of the generated IoT device onboarding policy
    Value: !GetAtt DeviceOnboardingPolicy.PolicyName

