final_template:
AWSTemplateFormatVersion: '2010-09-09'
Description: Creates a CloudFormation macro and Lambda function to dynamically generate IAM policies for the Datadog integration role.

Resources:
  DatadogPolicyMacroMacroFunction:
    Type: AWS::Serverless::Function
    Properties:
      FunctionName: DatadogPolicyMacroMacroFunction
      Runtime: python3.14
      Handler: index.handler
      Timeout: 10
      InlineCode: |
        import json

        def handler(event, context):
            try:
                fragment = event["fragment"]
                params = event.get("templateParameterValues", {})
                policy_type = params.get("PolicyType", "")

                if policy_type == "LogArchive":
                    policy = {
                        "DatadogLogArchiveAndRehydratePolicy": {
                            "Type": "AWS::IAM::ManagedPolicy",
                            "Properties": {
                                "PolicyDocument": {
                                    "Version": "2012-10-17",
                                    "Statement": [
                                        {
                                            "Effect": "Allow",
                                            "Action": [
                                                "s3:GetObject",
                                                "s3:PutObject",
                                                "s3:ListBucket"
                                            ],
                                            "Resource": "*"
                                        }
                                    ]
                                }
                            }
                        }
                    }
                    fragment["Resources"].update(policy)
                elif policy_type == "CloudTrail":
                    policy = {
                        "DatadogCloudTrailsPolicy": {
                            "Type": "AWS::IAM::ManagedPolicy",
                            "Properties": {
                                "PolicyDocument": {
                                    "Version": "2012-10-17",
                                    "Statement": [
                                        {
                                            "Effect": "Allow",
                                            "Action": [
                                                "s3:ListBucket",
                                                "s3:GetObject",
                                                "s3:GetBucketLocation"
                                            ],
                                            "Resource": "*"
                                        }
                                    ]
                                }
                            }
                        }
                    }
                    fragment["Resources"].update(policy)

                return {
                    "requestId": event["requestId"],
                    "status": "success",
                    "fragment": fragment
                }
            except Exception as e:
                return {
                    "requestId": event.get("requestId", ""),
                    "status": "failure",
                    "errorMessage": str(e)
                }

  DatadogPolicy:
    Type: AWS::CloudFormation::Macro
    Properties:
      Name: DatadogPolicy
      Description: Dynamically generates IAM policies for the Datadog integration role.
      FunctionName: !GetAtt DatadogPolicyMacroMacroFunction.Arn

Outputs:
  DatadogPolicyMacroName:
    Description: Name of the CloudFormation macro
    Value: !Ref DatadogPolicy
  DatadogPolicyMacroFunctionArn:
    Description: ARN of the macro handler Lambda function
    Value: !GetAtt DatadogPolicyMacroMacroFunction.Arn

AWSTemplateFormatVersion: '2010-09-09'
Description: Simple Todo GraphQL API on AWS AppSync backed by DynamoDB with JavaScript resolvers
Resources:
  TodoTable:
    Type: AWS::DynamoDB::Table
    Properties:
      TableName: !Sub ${AWS::StackName}-todos
      BillingMode: PAY_PER_REQUEST
      AttributeDefinitions:
        - AttributeName: id
          AttributeType: S
        - AttributeName: owner
          AttributeType: S
      KeySchema:
        - AttributeName: id
          KeyType: HASH
      GlobalSecondaryIndexes:
        - IndexName: ownerIndex
          KeySchema:
            - AttributeName: owner
              KeyType: HASH
          Projection:
            ProjectionType: ALL
      PointInTimeRecoverySpecification:
        PointInTimeRecoveryEnabled: true
      SSESpecification:
        SSEEnabled: true

  AppSyncServiceRole:
    Type: AWS::IAM::Role
    Properties:
      AssumeRolePolicyDocument:
        Version: '2012-10-17'
        Statement:
          - Effect: Allow
            Principal:
              Service: appsync.amazonaws.com
            Action: sts:AssumeRole
      Policies:
        - PolicyName: DynamoDBAccess
          PolicyDocument:
            Version: '2012-10-17'
            Statement:
              - Effect: Allow
                Action:
                  - dynamodb:GetItem
                  - dynamodb:PutItem
                  - dynamodb:UpdateItem
                  - dynamodb:DeleteItem
                  - dynamodb:Query
                  - dynamodb:Scan
                Resource:
                  - !GetAtt TodoTable.Arn
                  - !Sub ${TodoTable.Arn}/index/*

  SimpleTodoAPI:
    Type: AWS::AppSync::GraphQLApi
    Properties:
      Name: SimpleTodoAPI
      AuthenticationType: API_KEY
      XrayEnabled: false

  SimpleTodoApiKey:
    Type: AWS::AppSync::ApiKey
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Expires: 1780000000

  SimpleTodoSchema:
    Type: AWS::AppSync::GraphQLSchema
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Definition: |
        type Todo {
          id: ID!
          owner: String!
          title: String!
          description: String
          status: String!
          createdAt: AWSDateTime!
          updatedAt: AWSDateTime!
        }
        input CreateTodoInput {
          owner: String!
          title: String!
          description: String
          status: String
        }
        input UpdateTodoInput {
          id: ID!
          title: String
          description: String
          status: String
        }
        type Mutation {
          createTodo(input: CreateTodoInput!): Todo
          updateTodo(input: UpdateTodoInput!): Todo
          deleteTodo(id: ID!): Todo
        }
        type Query {
          getTodo(id: ID!): Todo
          listTodos: [Todo]
          todosByOwner(owner: String!): [Todo]
        }
        schema {
          query: Query
          mutation: Mutation
        }

  TodoDataSource:
    Type: AWS::AppSync::DataSource
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      Name: TodoTableDataSource
      Type: AMAZON_DYNAMODB
      ServiceRoleArn: !GetAtt AppSyncServiceRole.Arn
      DynamoDBConfig:
        TableName: !Ref TodoTable
        AwsRegion: !Ref AWS::Region

  CreateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: createTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';
        export function request(ctx) {
          const { input } = ctx.args;
          const id = util.autoId();
          const now = util.time.nowISO8601();
          return {
            operation: 'PutItem',
            key: util.dynamodb.toMapValues({ id }),
            attributeValues: util.dynamodb.toMapValues({
              owner: input.owner,
              title: input.title,
              description: input.description || null,
              status: input.status || 'PENDING',
              createdAt: now,
              updatedAt: now,
            }),
          };
        }
        export function response(ctx) {
          return ctx.result;
        }

  UpdateTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: updateTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';
        export function request(ctx) {
          const { input } = ctx.args;
          const { id, ...values } = input;
          const sets = [];
          const expNames = {};
          const expValues = {};
          for (const [key, value] of Object.entries(values)) {
            if (value !== undefined && value !== null) {
              sets.push(`#${key} = :${key}`);
              expNames[`#${key}`] = key;
              expValues[`:${key}`] = util.dynamodb.toDynamoDB(value);
            }
          }
          sets.push('#updatedAt = :updatedAt');
          expNames['#updatedAt'] = 'updatedAt';
          expValues[':updatedAt'] = util.dynamodb.toDynamoDB(util.time.nowISO8601());
          return {
            operation: 'UpdateItem',
            key: util.dynamodb.toMapValues({ id }),
            update: {
              expression: `SET ${sets.join(', ')}`,
              expressionNames: expNames,
              expressionValues: expValues,
            },
          };
        }
        export function response(ctx) {
          return ctx.result;
        }

  DeleteTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Mutation
      FieldName: deleteTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';
        export function request(ctx) {
          return {
            operation: 'DeleteItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }
        export function response(ctx) {
          return ctx.result;
        }

  GetTodoResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: getTodo
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        import { util } from '@aws-appsync/utils';
        export function request(ctx) {
          return {
            operation: 'GetItem',
            key: util.dynamodb.toMapValues({ id: ctx.args.id }),
          };
        }
        export function response(ctx) {
          return ctx.result;
        }

  ListTodosResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt SimpleTodoAPI.ApiId
      TypeName: Query
      FieldName: listTodos
      DataSourceName: !GetAtt TodoDataSource.Name
      Runtime:
        Name: APPSYNC_JS
        RuntimeVersion: 1.0.0
      Code: |
        export function request(ctx) {
          return {
            operation: 'Scan',
            limit: 100,
          };
        }
        export function response(ctx) {
          return ctx.result.items;
        }

  TodosByOwnerResolver:
    Type: AWS::AppSync::Resolver
    Properties:
      ApiId: !GetAtt SimpleTodo
